  "subtitle": "JSON पेस्ट या अपलोड करें, फ़्लैटन की हुई टेबल का प्रीव्यू देखें, अपना डिलिमिटर चुनें, और स्प्रेडशीट-सुरक्षित CSV डाउनलोड करें। नेस्टेड ऑब्जेक्ट डॉट-पाथ कॉलम बन जाते हैं, और जो फ़ील्ड स्प्रेडशीट फ़ॉर्मूला बन सकती हैं वे एक्सपोर्ट से पहले चिह्नित हो जाती हैं। कुछ भी अपलोड नहीं होता, कभी नहीं।",
  "quickAnswerTitle": "संक्षेप में: यह टूल क्या करता है?",
  "quickAnswer": "यह इसी ब्राउज़र टैब में ऑब्जेक्टों के JSON ऐरे को CSV पंक्तियों में बदलता है। हर ऑब्जेक्ट एक पंक्ति बनता है; नेस्टेड ऑब्जेक्ट address.city जैसे डॉट-पाथ कॉलम में फ़्लैट हो जाते हैं, सादे मानों की सूची एक ही सेल में '; ' से जुड़ जाती है, और ऑब्जेक्टों वाली सूची एक ही सेल में कॉम्पैक्ट JSON टेक्स्ट के रूप में रहती है — क्योंकि एक रिकॉर्ड एक ही पंक्ति में रहना चाहिए। कॉमा, सेमीकॉलन या टैब डिलिमिटर चुनें, नतीजे का प्रीव्यू देखें, फिर डाउनलोड या कॉपी करें। सेफ़-एक्सपोर्ट विकल्प उन फ़ील्डों की रक्षा करता है जो =, +, - या @ से शुरू होती हैं, ताकि स्प्रेडशीट उन्हें फ़ॉर्मूला न समझे।",
