  "errorMixedArray": "यह ऐरे ऑब्जेक्टों को सादे मानों या नेस्टेड ऐरे के साथ मिला रहा है, इसलिए यह साफ़ टेबल नहीं बन सकता। हर आइटम को ऑब्जेक्ट बनाएँ — या, साधारण सूची के लिए, ऑब्जेक्ट हटा दें ताकि हर मान एक 'value' कॉलम में आए।",
  "errorNoColumns": "इन ऑब्जेक्टों में कोई फ़ील्ड नहीं है, इसलिए एक्सपोर्ट के लिए कोई कॉलम नहीं। CSV को हर पंक्ति में कम से कम एक नाम वाला फ़ील्ड चाहिए।",
  "errorShape": "CSV को पंक्तियाँ चाहिए, और एक संख्या, टेक्स्ट मान या true/false टेबल नहीं बन सकते। अपने रिकॉर्डों को ऑब्जेक्टों के ऐरे में लपेटें — [{\"id\":1},{\"id\":2}] — या एक ऑब्जेक्ट पेस्ट करके उसे एक पंक्ति के रूप में बदलें।",
