  "exampleIntro": "मान लीजिए किसी विज़िटर ने आपके सर्च बॉक्स में नीचे दिया वाक्यांश टाइप किया। इसमें स्पेस और क्वेरी स्ट्रिंग चलाने वाले तीन कैरेक्टर हैं: &, = और ?। देखिए हर मोड इसका क्या करता है:",
  "exampleNote": "फ़ुल-URL मोड में & और = सक्रिय रहते हैं, इसलिए ?q=cookies%20&%20cream… पढ़ने वाला सर्वर मानता है कि q सिर्फ़ “cookies” है, और बाकी आवारा पैरामीटर बन जाता है — खोज शुरू होने से पहले ही बिगड़ जाती है। सिंगल वैल्यू मोड & को %26, = को %3D और ? को %3F में एनकोड करता है, इसलिए पूरा वाक्यांश एक ही मान के रूप में पहुँचता है। आम नियम: पूरा लिंक → फ़ुल URL मोड; लिंक के अंदर एक मान → सिंगल वैल्यू मोड। पहले से एनकोड मान को फिर एनकोड करने से डबल-एनकोडिंग होती है (%20 बन जाता है %2520), इसलिए ठीक एक बार एनकोड करें।",
  "exampleTitle": "मोड क्यों मायने रखता है — एक काम का उदाहरण",
  "exampleValueLabel": "कच्चा मान",
  "functionNote": "इस बार इस्तेमाल हुआ: {fn}",
  "honestText": "प्रतिशत-एनकोडिंग सिर्फ़ कैरेक्टरों को फिर से लिखती है ताकि URL उन्हें सुरक्षित ढो सके; जो %26 देखता है वह इसी टूल से उसे तुरंत & में बदल सकता है। यह कुछ नहीं छिपाती और कुछ नहीं बचाती: कभी भी पासवर्ड, API की, टोकन या कोई और गुप्त चीज़ URL में यह सोचकर न डालें कि एनकोडिंग उसे सुरक्षित रखेगी — नहीं रखेगी। गैर-लैटिन टेक्स्ट (उर्दू, जापानी, इमोजी) UTF-8 बाइट्स के रूप में एनकोड होता है, इसीलिए एक कैरेक्टर कई %XX समूह बन सकता है, और डिकोडिंग उसी UTF-8 की उम्मीद करती है। यह टूल डिकोडिंग के समय असली + को + ही रखता है; पुराने फ़ॉर्म डेटा में + का मतलब स्पेस हो सकता है, इसलिए अगर डिकोड किया मान ऐसा लगे कि उसके स्पेस ग़ायब हैं, तो यही वजह होने की संभावना है।",
