  "quickAnswer": "यह आपके ब्राउज़र के अपने URI फ़ंक्शन से टेक्स्ट को प्रतिशत-एनकोड या डिकोड करता है। फ़ुल URL मोड (encodeURI/decodeURI) लिंक का : / ? & = # स्ट्रक्चर जस का तस रखता है और सिर्फ़ असुरक्षित कैरेक्टर ठीक करता है; सिंगल वैल्यू मोड (encodeURIComponent/decodeURIComponent) उन स्ट्रक्चर कैरेक्टरों को भी एनकोड करता है — एक क्वेरी मान के लिए यही चाहिए। गैर-अंग्रेज़ी टेक्स्ट UTF-8 के रूप में संभाला जाता है। एनकोडिंग ट्रांसपोर्ट के लिए फ़ॉर्मेटिंग है — यह एन्क्रिप्शन नहीं है और कोई सुरक्षा नहीं देती।",
