  "pageTitle": "Unix टाइमस्टैम्प बदलें — सेकंड या मिलीसेकंड का अंदाज़ा नहीं",
  "subtitle": "epoch मान पेस्ट करें और UTC व अपना लोकल समय आमने-सामने देखें, पहचानी गई यूनिट खुलकर बताई जाती है। किसी भी तारीख़ को वापस सेकंड और मिलीसेकंड में बदलें। सब कुछ इसी टैब में होता है।",
  "quickAnswerTitle": "संक्षेप में: यह टूल क्या करता है?",
  "quickAnswer": "यह Unix टाइमस्टैम्प (1 जनवरी 1970, 00:00:00 UTC के बाद के सेकंड) को पढ़ने लायक तारीख़ों में बदलता है और वापस भी। संख्या पेस्ट करें और यह सेकंड बनाम मिलीसेकंड खुद पहचानता है — 1,000,000,000,000 या इससे बड़े मान मिलीसेकंड माने जाते हैं, छोटे सेकंड — और हमेशा बताता है कि उसने कौन सी यूनिट मानी, मैन्युअल ओवरराइड के साथ। नतीजे UTC और आपका लोकल समय आमने-सामने दिखाते हैं, साथ में कॉपी करने लायक ISO 8601। कुछ भी अपलोड नहीं होता।",
  "nowTitle": "मौजूदा Unix समय (लाइव)",
  "secondsLabel": "सेकंड",
  "millisecondsLabel": "मिलीसेकंड",
  "nowNote": "यह घड़ी आपके अपने डिवाइस की घड़ी है। अगर आपके डिवाइस का समय ग़लत है, तो यह संख्या भी उतनी ही ग़लत होगी।",
  "toDateTitle": "टाइमस्टैम्प → तारीख़",
  "inputLabel": "Unix टाइमस्टैम्प",
  "inputPlaceholder": "जैसे 1735689600 या 1735689600000",
