  "modeAuto": "खुद पहचानें (सुझाव)",
  "errorText": "यह सही पूर्ण-संख्या टाइमस्टैम्प नहीं है। सिर्फ़ अंक पेस्ट करें (1970 से पहले की तारीख़ों के लिए शुरू में माइनस ठीक है), संख्या के अंदर कॉमा, स्पेस या दशमलव बिंदु न हो।",
  "emptyHint": "ऊपर टाइमस्टैम्प पेस्ट करें। 0 (खुद epoch), 1735689600 (सेकंड) या 1735689600000 (मिलीसेकंड) आज़माएँ और देखें कि मानी गई यूनिट कैसे बदलती है।",
  "assumedText": "मान्यता: यह मान {unit} माना गया। अगर आपका स्रोत दूसरी यूनिट इस्तेमाल करता है तो ऊपर का सेलेक्टर बदलें।",
