  "passwordGeneratorDesc": "मुफ़्त पासवर्ड जेनरेटर। ब्राउज़र में ही लंबाई, सिंबल और पासफ़्रेज़ विकल्पों के साथ मज़बूत रैंडम पासवर्ड बनाएं। कुछ अपलोड नहीं, बिना साइन-अप।",
