  "pdfSplitterDesc": "मुफ़्त PDF स्प्लिटर। पेज-रेंज को एक PDF में निकालें या हर रेंज को अलग PDF में बाँटें — पूरी तरह ब्राउज़र में pdf-lib के साथ; आपकी फ़ाइल कभी अपलोड नहीं होती। पासवर्ड-संरक्षित या क्षतिग्रस्त PDF साफ़ संदेश के साथ विफल होते हैं। बिना साइन-अप।",
