  "pdfToolsDesc": "मुफ़्त PDF टूल्स। कई PDF एक में जोड़ें या JPG/PNG इमेज को PDF में बदलें — सब आपके ब्राउज़र में, बिना अपलोड, बिना साइन-अप।",
  "pdfToolsTitle": "मुफ़्त PDF टूल्स ऑनलाइन — PDF जोड़ें और इमेज को PDF बनाएं | ToolVena",
  "randomNumberDesc": "ब्राउज़र की क्रिप्टोग्राफ़िक रैंडमनेस से किसी भी रेंज में निष्पक्ष रैंडम नंबर निकालें। दोहराव की अनुमति या रोक, क्रमबद्ध नतीजे, सिक्का उछालें या पासा फेंकें — सब लोकल, कुछ अपलोड नहीं।",
  "randomNumberTitle": "रैंडम नंबर जेनरेटर — निष्पक्ष नंबर, सिक्का और पासा | ToolVena",
  "readingTimeDesc": "मुफ़्त पढ़ने-का-समय कैलकुलेटर। मौन पढ़ने का समय और बोलने/प्रेज़ेंटेशन का समय अनुमानित करें — समायोज्य WPM गति और विराम-भत्ते के साथ। लोकल चलता है, कुछ अपलोड नहीं।",
