  "regexTesterDesc": "मुफ़्त रेगेक्स टेस्टर। हाइलाइट मैच, कैप्चर ग्रुप, फ़्लैग और रिप्लेस प्रीव्यू के साथ रेगुलर एक्सप्रेशन लाइव जांचें, साथ में सामान्य-पैटर्न उदाहरण। JavaScript RegExp, पूरी तरह लोकल — कुछ अपलोड नहीं।",
  "regexTesterTitle": "रेगेक्स टेस्टर — पैटर्न, ग्रुप और रिप्लेस ऑनलाइन जांचें, मुफ़्त | ToolVena",
  "seoDesc": "Google के लिए मेटा टाइटल आइडिया, डिस्क्रिप्शन ड्राफ़्ट और YouTube Shorts, TikTok व ब्लॉग के लिए हैशटैग आइडिया बनाएं — बिना पैसे खर्च किए।",
  "seoTitle": "SEO मेटा और हैशटैग जेनरेटर — टाइटल, डिस्क्रिप्शन और टैग आइडिया | ToolVena",
  "slugGeneratorDesc": "मुफ़्त स्लग जेनरेटर। टाइटल पेस्ट करें और हाइफ़न या अंडरस्कोर सेपरेटर वाला लोअरकेस URL स्लग पाएं — अंग्रेज़ी स्टॉप-वर्ड हटाना, एक्सेंट हैंडलिंग और बैच मोड। ब्राउज़र में ही, कुछ अपलोड नहीं।",
  "slugGeneratorTitle": "मुफ़्त स्लग जेनरेटर — टाइटल को साफ़ URL स्लग बनाएं | ToolVena",
  "summarizerDesc": "मुफ़्त टेक्स्ट सारांश टूल। लंबे लेख, पेपर और दस्तावेज़ पेस्ट करें — 8 भाषाओं में तुरंत एक्सट्रैक्टिव सारांश पाएं। बिना साइन-अप।",
  "summarizerTitle": "मुफ़्त टेक्स्ट सारांश टूल — लेख और दस्तावेज़ का सार बनाएं | ToolVena",
  "textRepeaterDesc": "मुफ़्त टेक्स्ट रिपीटर। कोई भी शब्द, वाक्य या इमोजी 1,000 बार तक दोहराएं — स्पेस, नई लाइन, कॉमा या अपने सेपरेटर के साथ। कॉपी या डाउनलोड करें। कुछ अपलोड नहीं।",
