  "textToSpeechDesc": "मुफ़्त टेक्स्ट-टू-स्पीच। टेक्स्ट पेस्ट करें और अपने डिवाइस की अपनी आवाज़ों में सुनें, सीधे ब्राउज़र में। बिना साइन-अप, कुछ अपलोड नहीं।",
