  "timestampConverterDesc": "मुफ़्त यूनिक्स टाइमस्टैम्प कन्वर्टर। लाइव epoch घड़ी, सेकंड बनाम मिलीसेकंड की ऑटो-पहचान (अनुमान दिखता है), UTC और लोकल समय साथ-साथ, कॉपी योग्य ISO 8601, और तारीख़ से सेकंड व मिलीसेकंड में टाइमस्टैम्प। पूरी तरह लोकल — कुछ अपलोड नहीं।",
  "timestampConverterTitle": "यूनिक्स टाइमस्टैम्प कन्वर्टर — तारीख़, UTC और लोकल समय, मुफ़्त | ToolVena",
  "typingTestDesc": "मुफ़्त टाइपिंग स्पीड टेस्ट। 30 और 60 सेकंड के टाइमर टेस्ट के साथ 25/50 शब्द मोड, लाइव WPM, सटीकता और अक्षर आँकड़े। बिना साइन-अप, कुछ अपलोड नहीं।",
