  "unitConverterDesc": "मुफ़्त यूनिट कन्वर्टर। लंबाई, वज़न, तापमान, आयतन, क्षेत्रफल, गति, समय, डेटा, दबाव और ऊर्जा — असली फ़ैक्टर, दिखते फ़ॉर्मूले और प्रीसेट के साथ। कोई मुद्रा नहीं, बिना साइन-अप, कुछ अपलोड नहीं।",
