  "urlEncoderDesc": "मुफ़्त URL एनकोडर और डिकोडर। encodeURI से पूरा URL या encodeURIComponent से एक क्वेरी वैल्यू एनकोड करें, अमान्य परसेंट-सीक्वेंस पर साफ़ भाषा की एरर के साथ डिकोड करें। UTF-8 सेफ़, पूरी तरह लोकल — कुछ अपलोड नहीं। एनकोडिंग एन्क्रिप्शन नहीं है।",
