  "utmLinkBuilderDesc": "मुफ़्त UTM लिंक बिल्डर। लाइव प्रीव्यू, सही एनकोडिंग, कॉपी बटन और डिवाइस-पर प्रीसेट के साथ utm_source, utm_medium, utm_campaign, utm_term और utm_content जोड़ें। UTM सही रिपोर्टिंग की गारंटी नहीं देते। पूरी तरह लोकल — कुछ अपलोड नहीं।",
